document.body.textContent = 'network-guard-image';
const image = new Image();
image.onload = () => console.log('EXTERNAL_IMAGE_LOADED', image.naturalWidth);
image.onerror = () => console.warn('network image refused');
image.src = "https://cw-qc-network.invalid/image.svg?nonce=muil8108";
